insert into stages(id,phase,ord,name,cls,draft,question,deliverable,criteria,approvals,deps) values ('s0a',0,0,'הבנה ברמה טכנולוגית','u',true,'מהי הטכנולוגיה, איך היא עובדת ומה מצב הבשלות שלה (TRL)?','דף הסבר טכנולוגי בפורמט אחיד (עד 2 עמודים): עקרון פעולה, רכיבים, TRL, מילון מונחים.','["הסבר מובן לקורא שאינו מומחה","הערכת TRL מנומקת","רשימת מקורות פתוחים"]'::jsonb,'["אמיר"]'::jsonb,'["מקורות פתוחים, מאמרים, כנסים"]'::jsonb) on conflict (id) do nothing;
